12	    private static final char Hyphen_Minus = '-';
13	    private static final char Unicode_Null = '\u0000';
14	    private static final char Replacement = '\uFFFD';
15	
16	    private final CharacterReader reader;
17	
18	    /**
19	     Create a new TokenQueue.
20	     @param data string of data to back queue.
21	     */
22	    public TokenQueue(String data) {
23	        reader = new CharacterReader(data);
24	    }
25	
26	    /**
27	     Is the queue empty?
28	     @return true if no data left in queue.
29	     */
30	    public boolean isEmpty() {
31	        return reader.isEmpty();
32	    }
33	
34	    /**
35	     Consume one character off queue.
36	     @return first character on queue.
37	     */
38	    public char consume() {
39	        return reader.consume();
40	    }
41	
42	    /**
43	     Drops the next character off the queue.
44	     */
45	    public void advance() {
46	        if (!isEmpty()) reader.advance();
47	    }
48	
49	    char current() {
50	        return reader.current();
51	    }
52	
53	    /**
54	     Tests if the next characters on the queue match the sequence, case-insensitively.
55	     @param seq String to check queue for.
56	     @return true if the next characters match.
57	     */
58	    public boolean matches(String seq) {
59	        return reader.matchesIgnoreCase(seq);
60	    }
61	
62	    /** Tests if the next character on the queue matches the character, case-sensitively. */
63	    public boolean matches(char c) {
64	        return reader.matches(c);
65	    }
66	
67	    /**
