82	        return reader.matchConsumeIgnoreCase(seq);
83	    }
84	
85	    /** If the queue matches the supplied (case-sensitive) character, consume it off the queue. */
86	    public boolean matchChomp(char c) {
87	        if (reader.matches(c)) {
88	            consume();
89	            return true;
90	        }
91	        return false;
92	    }
93	
94	    /**
95	     Tests if queue starts with a whitespace character.
96	     @return if starts with whitespace
97	     */
