    if ("odd".equals(arg)) {
        step = 2;
        offset = 1;
    } else if ("even".equals(arg)) {
        step = 2;
        offset = 0;
    } else {
        Matcher stepOffsetM, stepM;
        if ((stepOffsetM = NthStepOffset.matcher(arg)).matches()) {
            if (stepOffsetM.group(3) != null) // has digits, like 3n+2 or -3n+2
                step = Integer.parseInt(stepOffsetM.group(1).replaceFirst("^\\+", ""));
            else // no digits, might be like n+2, or -n+2. if group(2) == "-", it’s -1;
                step = "-".equals(stepOffsetM.group(2)) ? -1 : 1;
            offset =
                stepOffsetM.group(4) != null ? Integer.parseInt(stepOffsetM.group(4).replaceFirst("^\\+", "")) : 0;
        } else if ((stepM = NthOffset.matcher(arg)).matches()) {
            step = 0;
            offset = Integer.parseInt(stepM.group().replaceFirst("^\\+", ""));
        } else {
            throw new Selector.SelectorParseException("Could not parse nth-index '%s': unexpected format", arg);
        }
    }

    Evaluator ofSelector = null;
    if (consumeOfClause()) {
        if (ofType)
            throw new Selector.SelectorParseException(
                "Could not parse query '%s': 'of S' is only supported by :nth-child() and :nth-last-child()", query);
        ofSelector = parseSelectorGroup();
    }
    Validate.isTrue(tq.matchChomp(')'), "Could not parse query '%s': expected ')' in nth-child argument", query);

    if (ofSelector != null)
        return last
            ? new Evaluator.IsNthLastChildOfSelector(step, offset, ofSelector)
            : new Evaluator.IsNthChildOfSelector(step, offset, ofSelector);

    return ofType
        ? (last ? new Evaluator.IsNthLastOfType(step, offset) : new Evaluator.IsNthOfType(step, offset))
        : (last ? new Evaluator.IsNthLastChild(step, offset) : new Evaluator.IsNthChild(step, offset));
}

/**
 Consume the An+B (or odd/even) formula at the current position, leaving the queue positioned at the start of an
 optional " of S" clause, or at the closing paren. Whitespace inside the formula (e.g. {@code 2n + 1}) is
 compacted.
 */
private String consumeNthFormula() {
    StringBuilder sb = new StringBuilder();
    while (!tq.isEmpty() && !tq.matches(')')) {
        if (tq.matchesWhitespace()) {
            tq.consumeWhitespace();
            if (tq.matches("of") && !tqMatchesIdent()) { // "of" keyword, not e.g. an "ofx" ident
                return sb.toString();
            }
            if (sb.length() > 0 && !tq.matches(')')) sb.append(' '); // preserve sign spacing, e.g. "-n+ 2" -> "-n+ 2"
            continue;
        }
        sb.append(tq.consume());
    }
    return sb.toString();
}

/** After the formula, consume an optional " of " keyword; returns true if an of-selector follows. */
private boolean consumeOfClause() {
    // consumeNthFormula leaves us on "of", at ')', or at a non-whitespace token
    if (tq.matchChomp("of") && !tqMatchesIdent()) {
        tq.consumeWhitespace();
        return true;
    }
    return false;
}

/** Is the current position the continuation of an identifier (so a match like "ofx" is not a keyword)? */
private boolean tqMatchesIdent() {
    return !tq.isEmpty() && Character.isLetterOrDigit(tq.current());
}

