import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.jsoup.select.Elements;

public class Scratch {
    static void show(String label, String css, String html) {
        try {
            Elements e = Jsoup.parse(html).select(css);
            System.out.println(label + ": [" + String.join(", ", e.eachText()) + "]");
        } catch (Exception ex) {
            System.out.println(label + ": ERROR " + ex.getMessage());
        }
    }
    public static void main(String[] a) {
        String html = "<ul><li class='a b'>1</li><li>2</li><li class='a'>3</li></ul>";
        show("dedupe both-list-items", "ul :nth-child(1 of .a, .b)", html);
        show("nth inside not", "ul :not(:nth-child(2 of .a))", html);
        show("missing selector", ":nth-child(1 of)", html);
        show("missing formula", ":nth-child(of .a)", html);
        show("unbalanced", ":nth-child(1 of .a", html);
        show("no space before of", ":nth-child(1of .a)", html);
        show("trailing comma in of", ":nth-child(1 of .a,)", html);
        show("of on nth-of-type", "li:nth-of-type(1 of .a)", html);
        show("nested nth in of", "ul :nth-child(1 of li:nth-child(3))", html);
        show("empty parens", ":nth-child()", html);
        // compiled evaluator reuse across documents
        Evaluator ev = Selector.evaluatorOf("ul :nth-child(2 of .a)");
        Document d1 = Jsoup.parse(html);
        System.out.println("reuse d1: " + d1.select(ev).eachText());
        Document d2 = Jsoup.parse("<ul><li class=a>x</li><li class=a>y</li><li class=a>z</li></ul>");
        System.out.println("reuse d2: " + d2.select(ev).eachText());
        // mutation on d1 then reuse
        d1.select("li").first().remove();
        System.out.println("reuse d1 after remove: " + d1.select(ev).eachText());
        // second parent scope: siblings across parents
        show("two parents", ".w :nth-child(1 of .a)",
            "<div class=w><p class=a>1</p></div><div class=w><p class=a>2</p></div>");
        // whitespace 2n + 1
        show("spaced formula", "ul :nth-child( 2n + 1 of .a )", html);
        System.out.println("toString: " + ev);
    }
}
